-- CAREEROS P3-T03: AI usage metering (phase plan D5). The CREATE TABLE and index statements are generated by
-- drizzle-kit; the row-level security and the privileges are written by hand, following audit_log (P3-T01). Runs as the
-- migration (owner) role. Down migration: down.sql in this folder.
--> statement-breakpoint
CREATE TABLE "ai_usage" (
	"id" text PRIMARY KEY DEFAULT public.careeros_uuidv7()::text,
	"organization_id" text NOT NULL,
	"user_id" text,
	"source" text NOT NULL,
	"feature" text NOT NULL,
	"provider" text NOT NULL,
	"model" text NOT NULL,
	"input_tokens" integer DEFAULT 0 NOT NULL,
	"output_tokens" integer DEFAULT 0 NOT NULL,
	"cached_input_tokens" integer DEFAULT 0 NOT NULL,
	"cost_usd_micros" bigint DEFAULT 0 NOT NULL,
	"credits" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ai_usage_source_check" CHECK ("source" in ('platform', 'own_key'))
);
--> statement-breakpoint
CREATE INDEX "ai_usage_org_created_idx" ON "ai_usage" ("organization_id","created_at");--> statement-breakpoint
ALTER TABLE "ai_usage" ADD CONSTRAINT "ai_usage_organization_id_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organization"("id") ON DELETE CASCADE;--> statement-breakpoint
ALTER TABLE "ai_usage" ADD CONSTRAINT "ai_usage_user_id_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "user"("id") ON DELETE SET NULL;--> statement-breakpoint
-- Row-level security: FORCE applies the policy to the table owner too, so only owner_access lets the owner role see every
-- organization. careeros_app matches its own organization only; an unset setting is NULL and matches nothing (fail
-- closed). The app role may read and insert rows of the current organization and has no UPDATE or DELETE policy, so a
-- row can be neither changed nor removed by the application (a blanket table grant would not help: with FORCE RLS a
-- command without a policy is denied).
ALTER TABLE "ai_usage" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "ai_usage" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS "tenant_isolation" ON "ai_usage";--> statement-breakpoint
CREATE POLICY "tenant_isolation" ON "ai_usage" FOR SELECT
	USING ("organization_id" = current_setting('app.current_org_id', true));--> statement-breakpoint
DROP POLICY IF EXISTS "tenant_insert" ON "ai_usage";--> statement-breakpoint
CREATE POLICY "tenant_insert" ON "ai_usage" FOR INSERT
	WITH CHECK ("organization_id" = current_setting('app.current_org_id', true));--> statement-breakpoint
DROP POLICY IF EXISTS "owner_access" ON "ai_usage";--> statement-breakpoint
CREATE POLICY "owner_access" ON "ai_usage" TO CURRENT_USER USING (true) WITH CHECK (true);--> statement-breakpoint
-- Table privileges: new tables get SELECT, INSERT, UPDATE and DELETE for careeros_app from the default privileges of
-- infra/db/bootstrap-roles.sql; take back UPDATE, DELETE and TRUNCATE. (A fresh test database migrates before the role
-- exists, so the REVOKE is conditional; the bootstrap script repeats it after its blanket GRANT.)
DO $$ BEGIN
	IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'careeros_app') THEN
		REVOKE UPDATE, DELETE, TRUNCATE ON TABLE public.ai_usage FROM careeros_app;
	END IF;
END $$;
